package com.booksyde.controller; import com.booksyde.dto.request.*; import com.booksyde.dto.response.BookResponse; import com.booksyde.service.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/books") public class BookController {private final BookService books; private final AuthenticatedUserService users; public BookController(BookService books,AuthenticatedUserService users){this.books=books;this.users=users;} @GetMapping("/public") public List<BookResponse> publicBooks(){return books.publicBooks();} @GetMapping public List<BookResponse> mine(@AuthenticationPrincipal Jwt jwt){var u=users.resolve(jwt);return books.owned(u.id(),u.roles());} @GetMapping("/{id}") public BookResponse get(@PathVariable UUID id,@AuthenticationPrincipal Jwt jwt){var u=users.resolve(jwt);return books.find(id,u.id(),u.roles());} @PostMapping public BookResponse create(@Valid @RequestBody CreateBookRequest r,@AuthenticationPrincipal Jwt jwt){var u=users.resolve(jwt);return books.create(r,u.id(),u.roles());} @PutMapping("/{id}") public BookResponse update(@PathVariable UUID id,@Valid @RequestBody UpdateBookRequest r,@AuthenticationPrincipal Jwt jwt){var u=users.resolve(jwt);return books.update(id,r,u.id(),u.roles());} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id,@AuthenticationPrincipal Jwt jwt){var u=users.resolve(jwt);books.delete(id,u.id(),u.roles());}}
